-- existían conservan su historia; lo que no está acá se desactiva (nunca se
-- borra). Requiere 0123.

-- ── Caminos ──
insert into public.caminos (slug, titulo_es, descripcion_es, domain_slug, orden, recompensa_puntos, active) values
('ducha-y-bano','El agua del baño','Del gesto de la canilla a encontrar la pérdida que nadie ve: el baño es donde más agua se va en una casa.','agua',1,300,true),
('separar-en-serio','Separar en serio','Saber cuándo pasa el camión, tener dónde separar, hacerlo bien y que llegue a quien lo recupera.','residuos',2,300,true),
('compost-en-casa','Compost en casa','De la yerba en la maceta a tu propia tierra negra: la mitad de tu basura puede volver a ser suelo.','residuos',3,300,true),
('cocina-sin-desperdicio','Cocina sin desperdicio','Que no se pierda nada de lo que comprás: primero lo que vence, porciones justas, freezer, heladera ordenada y un menú.','alimentacion',4,300,true),
('casa-sin-consumo-fantasma','Casa sin consumo fantasma','Lo que queda enchufado sin usarse puede ser hasta el 15% de la luz del año. Cazalo de a poco.','energia',5,300,true),
('cocina-eficiente','La cocina que gasta menos gas','Tapa, llama justa, el horno sólo cuando vale la pena, y una heladera bien regulada.','energia',6,300,true),
('mate-bien-hecho','El mate, bien hecho','La pava justa, sin hervir, el termo para toda la tarde y una pava sin sarro: el ritual de todos los días, sin gastar de más.','energia',7,300,true),
('moverte-liviano','Moverte liviano','De bajarte una parada antes a una semana entera yendo a pie o en bici a todo lo cercano.','movilidad',8,300,true),
('en-bici','La bici, de verdad','Una bici lista, una ruta segura, los primeros viajes y saber arreglarla: hasta poder enseñarle a otro.','movilidad',9,300,true),
('balcon-vivo','Balcón vivo','De una semilla de lo que comiste a un balcón con plantas nativas, agua para las aves y refugio para abejas.','plantas',10,300,true),
('huerta-en-casa','Tu primera huerta','Armarla, cuidar la tierra, sembrar de estación, cosechar y guardar tus propias semillas.','plantas',11,300,true),
('amigo-de-las-aves','Amigo de las aves','Vidrios que no matan, qué hacer con un pichón, a quién llamar, nunca comprar fauna y noches más oscuras.','animales',12,300,true),
('ojos-de-naturalista','Ojos de naturalista','Mirar, reconocer y registrar: de cinco minutos en la ventana a tus primeros datos para la ciencia.','ciencia',13,300,true),
('pequeno-naturalista','Pequeño naturalista','Un poroto que nace, un metro cuadrado lleno de vida, tu primer dibujo de un animal y un cuaderno propio.','ciencia',14,300,true),
('guardian-de-casa','Guardián de tu casa','Cinco misiones para chicos: las luces, el agua, el stand-by, los carteles y la basura de tu casa.','energia',15,300,true),
('comprar-mejor','Comprar mejor','La lista, esperar un día, usar lo que ya tenés, lo usado, reparar e intercambiar.','consumo',16,300,true),
('vecino-activo','Vecino activo','De levantar una botella de la vereda a organizar la limpieza del barrio.','comunidad',17,300,true),
('escuela-verde','Escuela verde','La colación sin envoltorios, el papel de los dos lados, las luces del recreo y una propuesta para toda la escuela.','comunidad',18,300,true),
('oficina-verde','Trabajo verde','Tu taza, tu puesto apagado, la impresora, la heladera compartida y una propuesta para todo el equipo.','comunidad',19,300,true)
on conflict (slug) do update set titulo_es = excluded.titulo_es, descripcion_es = excluded.descripcion_es,
  domain_slug = excluded.domain_slug, orden = excluded.orden, recompensa_puntos = excluded.recompensa_puntos, active = true;
update public.caminos set active = false where slug not in ('ducha-y-bano','separar-en-serio','compost-en-casa','cocina-sin-desperdicio','casa-sin-consumo-fantasma','cocina-eficiente','mate-bien-hecho','moverte-liviano','en-bici','balcon-vivo','huerta-en-casa','amigo-de-las-aves','ojos-de-naturalista','pequeno-naturalista','guardian-de-casa','comprar-mejor','vecino-activo','escuela-verde','oficina-verde');

-- ── Acciones ──
-- Primero se suelta el camino de todo (una acción puede haber cambiado de camino).
update public.activities set camino_slug = null, camino_paso = null where camino_slug is not null;

insert into public.activities (slug, type, domain_slug, title_es, short_es, description_es, instructions_es, effort, impact, verification, base_points, frequency, repeat_cooldown_hours, icon, min_rank_slug, age_groups, impact_water_l, impact_co2_kg, impact_waste_kg, impact_energy_kwh, impact_equivalency_es, routine_eligible, formato, minutos, costo, ahorra, requiere, lugar, estaciones, dias, regiones, con_adulto, medida, fuente, fuente_url, camino_slug, camino_paso, tags, otorga, active, sort_order) values
('ducha-corta-5-min','daily'::activity_type,'agua','Bañate en 5 minutos','Una ducha larga tira unos 10 litros por minuto, y casi todos calentados con gas.','La ducha es el mayor gasto de agua caliente de una casa. La Guía de Ahorro de Energía de la Ciudad recomienda no pasar de 10 minutos y, mejor, quedarse en 5. Tres minutos menos son unos 30 litros y el gas que hacía falta para calentarlos.','Elegí una canción o poné un timer de 5 minutos antes de abrir la ducha.
Mojate, cerrá para enjabonarte y abrí sólo para enjuagarte.
Cuando termina la canción, cerrás.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],30,0.244,0,1.35,'Cada vez: ~30 L de agua',true,'gesto',5,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Gobierno de la Ciudad de Buenos Aires','https://static.buenosaires.gob.ar/sites/default/files/2026-04/Gu%C3%ADa%20de%20ahorro%20de%20energ%C3%ADa%20en%20el%20hogar.pdf','ducha-y-bano',3,array['ducha','gas']::text[],null,true,1),
('agua-cerrar-mientras-shampoo','daily'::activity_type,'agua','Cerrá la ducha mientras te enjabonás','El shampoo y el jabón no necesitan el agua corriendo: son dos minutos de ducha que se van solos.','Mientras te enjabonás el pelo o el cuerpo, la ducha abierta tira agua caliente que nadie usa. Cerrarla esos dos minutos ahorra unos 20 litros y el gas de calentarlos, sin que la ducha sea más corta.','Mojate y cerrá la canilla.
Enjabonate el pelo y el cuerpo con la ducha cerrada.
Abrí de nuevo sólo para enjuagarte.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],20,0.162,0,0.9,'Cada vez: ~20 L de agua',true,'gesto',1,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/','ducha-y-bano',2,array['ducha']::text[],null,true,2),
('agua-balde-ducha-fria','daily'::activity_type,'agua','Juntá en un balde el agua fría de la ducha','Mientras esperás que salga caliente se van 5 a 8 litros de agua limpia por la rejilla.','Esos primeros litros fríos son agua potable que se tira sin usar. En un balde sirven para el inodoro, para baldear el patio o para regar. Es uno de los gestos que más agua rescata sin cambiar nada de tu ducha.','Dejá un balde en el baño.
Ponelo bajo la ducha mientras esperás que salga caliente.
Usá esa agua para el inodoro, las plantas o el piso.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],6,0,0,0,'Cada vez: ~6 L de agua',true,'gesto',2,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,'ducha-y-bano',4,array['ducha','reuso']::text[],null,true,3),
('cerra-la-canilla-mientras-te-cepillas-o-enjabona','daily'::activity_type,'agua','Cerrá la canilla mientras te lavás los dientes','Dos minutos de canilla abierta son unos 10 litros que se van sin tocarte.','Lavarse los dientes lleva dos minutos y la canilla abierta tira unos 5 litros por minuto. Abrirla sólo para mojar el cepillo y para enjuagarte alcanza de sobra. Si lo hacés dos veces por día, son más de 7.000 litros al año.','Mojá el cepillo y cerrá la canilla.
Cepillate con la canilla cerrada.
Enjuagate con un vaso o abriendo un momento.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],10,0,0,0,'Cada vez: ~10 L de agua',true,'gesto',2,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/','ducha-y-bano',1,array['baño','chicos']::text[],null,true,4),
('agua-manos-canilla-cerrada','daily'::activity_type,'agua','Enjabonate las manos con la canilla cerrada','Los 20 segundos de jabón son 20 segundos de canilla abierta que no hacen falta.','Lavarse bien las manos lleva unos 20 segundos de jabón. Con la canilla abierta todo ese tiempo se van 2 litros por lavado; con varios lavados por día, la cuenta crece rápido. Cerrarla mientras te frotás no cambia nada de la higiene.','Mojate las manos y cerrá la canilla.
Frotá con jabón, también entre los dedos.
Abrí para enjuagarte.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],4,0,0,0,'Cada vez: ~4 L de agua',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['baño','chicos']::text[],null,true,5),
('lava-los-platos-con-la-canilla-cerrada','daily'::activity_type,'agua','Enjaboná los platos con la canilla cerrada','Lavar con el agua corriendo es de los mayores desperdicios de la cocina.','Con la canilla abierta mientras enjabonás se van unos 6 litros por minuto. Enjabonar todo primero y enjuagar todo junto, de una pasada, usa una fracción. Si lavás con agua caliente, además ahorrás gas.','Juntá los platos y cerrá la canilla.
Enjaboná todo con la esponja.
Enjuagá todo junto, de una sola vez.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],20,0,0,0,'Cada vez: ~20 L de agua',true,'gesto',2,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['cocina']::text[],null,true,6),
('pone-el-lavarropas-solo-cuando-este-lleno','daily'::activity_type,'agua','Poné el lavarropas sólo con carga completa','Un lavado a medias usa casi la misma agua y la misma luz que uno lleno.','El lavarropas gasta casi lo mismo con media carga que llena: unos 50 litros por lavado en un automático. Esperar a completar el tambor ahorra lavados enteros a lo largo del mes. La guía de la Ciudad lo pone primero en su lista del lavarropas.','Juntá la ropa hasta completar la carga.
Si es urgente una sola prenda, lavala a mano.
Cuando esté lleno, lavá.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],40,0.093,0,0.3,'Cada vez: ~40 L de agua',false,'gesto',1,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Gobierno de la Ciudad de Buenos Aires','https://static.buenosaires.gob.ar/sites/default/files/2026-04/Gu%C3%ADa%20de%20ahorro%20de%20energ%C3%ADa%20en%20el%20hogar.pdf',null,null,array['lavarropas']::text[],null,true,7),
('agua-programa-corto','daily'::activity_type,'agua','Elegí el programa corto o eco del lavarropas','La ropa de todos los días no necesita el ciclo más largo.','La ropa usada un día no está sucia de verdad: el programa corto o eco la deja igual, con menos agua y menos luz. Guardá el ciclo largo para toallas, sábanas o ropa de trabajo con barro.','Mirá qué tan sucia está la carga.
Si es ropa de uso diario, elegí el programa corto o eco.
Usá agua fría salvo que haya manchas difíciles.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],20,0.093,0,0.3,'Cada vez: ~20 L de agua',false,'gesto',1,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Gobierno de la Ciudad de Buenos Aires','https://static.buenosaires.gob.ar/sites/default/files/2026-04/Gu%C3%ADa%20de%20ahorro%20de%20energ%C3%ADa%20en%20el%20hogar.pdf',null,null,array['lavarropas']::text[],null,true,8),
('agua-usar-dos-veces','daily'::activity_type,'agua','Usá la ropa más de una vez antes de lavarla','Un jean, un buzo o un pantalón aguantan varias puestas: lavarlos de más los gasta y tira agua.','Mucha ropa va al lavarropas por costumbre, no porque esté sucia. Si no tiene manchas ni olor, aireala una noche y volvé a usarla. Cada prenda que no se lava es parte de un lavado menos: agua, luz y una prenda que dura más.','Antes de tirar algo al canasto, fijate si está sucio de verdad.
Si no, colgalo al aire una noche.
Volvé a usarlo.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],15,0.031,0,0.1,'Cada vez: ~15 L de agua',false,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['ropa','lavarropas']::text[],null,true,9),
('agua-manchas-a-mano','daily'::activity_type,'agua','Sacá una mancha a mano en vez de lavar todo','Una mancha chica no justifica un lavado entero.','Frotar una mancha con un poco de jabón y agua salva una prenda que si no iría al lavarropas. Es más rápido, usa medio litro en vez de decenas, y la prenda se gasta menos.','Mojá sólo la parte manchada.
Frotá con jabón blanco o detergente.
Enjuagá, dejá secar y seguí usándola.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],10,0,0,0,'Cada vez: ~10 L de agua',false,'gesto',3,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['ropa']::text[],null,true,10),
('agua-lavar-verduras-en-bowl','daily'::activity_type,'agua','Lavá las verduras en un bowl, no bajo el chorro','Esa agua después riega perfecto una maceta.','Lavar la verdura bajo la canilla abierta tira varios litros por vez. En un bowl o una fuente con agua queda igual de limpia, y el agua que sobra sirve para regar.','Llená un bowl con agua.
Lavá ahí las verduras y las frutas, frotando las que tengan tierra.
Usá el agua que quedó para regar.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],10,0,0,0,'Cada vez: ~10 L de agua',true,'gesto',2,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['cocina','reuso']::text[],null,true,11),
('agua-remojar-ollas','daily'::activity_type,'agua','Dejá la olla en remojo en vez de rasparla bajo el chorro','Diez minutos de remojo ahorran diez minutos de canilla abierta.','Lo pegado sale solo si lo dejás en remojo mientras comés. Rasparlo con el agua corriendo es de lo que más agua tira en la cocina, y además cansa.','Apenas sirvas, poné un poco de agua y detergente en la olla.
Dejala mientras comés.
Lavala después, ya sin esfuerzo.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],12,0,0,0,'Cada vez: ~12 L de agua',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['cocina']::text[],null,true,12),
('agua-descongelar-heladera','daily'::activity_type,'agua','Descongelá en la heladera, no bajo la canilla','Descongelar con agua corriendo tira decenas de litros por vez.','Pasar lo congelado a la heladera la noche anterior descongela de forma pareja y segura, sin gastar agua. Además el frío que suelta ayuda a la heladera.','A la noche, pensá qué vas a cocinar mañana.
Pasalo del freezer a la heladera, en un plato.
Al otro día está listo.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['teen','adult']::text[],20,0,0,0,'Cada vez: ~20 L de agua',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['cocina']::text[],null,true,13),
('agua-regar-temprano','daily'::activity_type,'agua','Regá temprano o al atardecer','Al mediodía buena parte del riego se evapora antes de llegar a la raíz.','En los meses de calor, regar al mediodía es regar el aire. AySA recomienda hacerlo muy temprano o al caer el sol: la tierra lo absorbe, las plantas lo aprovechan y necesitás menos agua para el mismo resultado.','Regá antes de las 9 o después de las 19.
Regá la tierra, al pie de la planta, no las hojas.
Si la tierra está húmeda a un dedo de profundidad, esperá.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],5,0,0,0,'Cada vez: ~5 L de agua',false,'gesto',5,'gratis',false,array[]::text[],'casa',array['primavera','verano']::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/',null,null,array['riego','plantas']::text[],null,true,14),
('agua-tapon-en-la-pileta','daily'::activity_type,'agua','Poné el tapón antes de abrir la canilla','Para lavarte la cara o las manos alcanza con un poco de agua en la pileta.','Con el tapón puesto usás un litro de agua en vez de dejar correr varios. Sirve para lavarte la cara, afeitarte o enjuagar algo chico.','Tapá la pileta.
Llenala un poco.
Usá esa agua para lo que tengas que hacer.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],3,0,0,0,'Cada vez: ~3 L de agua',false,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['baño']::text[],null,true,15),
('agua-inodoro-no-papelera','daily'::activity_type,'agua','No uses el inodoro como tacho de basura','Cada descarga de más son unos 9 litros por un pañuelito.','Pañuelos, pelos, algodones o colillas en el inodoro gastan una descarga entera y tapan cañerías. Al tacho del baño van mejor: menos agua y menos problemas en la cloaca.','Dejá un tachito con tapa en el baño.
Tirá ahí pañuelos, algodones y pelos.
Descargá el inodoro sólo cuando lo usaste.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],9,0,0,0,'Cada vez: ~9 L de agua',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['baño']::text[],null,true,16),
('agua-reusar-agua-pastas','daily'::activity_type,'agua','Regá con el agua que te sobró','La de la pava, la del vaso o la de hervir verduras: fría, es agua para las plantas.','En una casa sobra agua limpia todo el tiempo: el fondo de la pava, el vaso que quedó, la cocción de las verduras sin sal. Una vez fría, regar con ella es agua que no sale de la canilla.','Dejá una jarra o botella cerca de la pileta de la cocina.
Volcá ahí el agua limpia que te sobre.
Cuando se enfríe, regá con ella.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],3,0,0,0,'Cada vez: ~3 L de agua',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['reuso','mate','plantas']::text[],null,true,17),
('agua-escoba-no-manguera','daily'::activity_type,'agua','Barré la vereda en vez de baldearla','Baldear con manguera tira más de 10 litros por minuto en la vereda.','Baldear la vereda es una costumbre muy nuestra, y una de las que más agua potable tira. Con escoba y pala queda igual de limpia; si hace falta, un balde con un poco de agua alcanza para lo pegado.','Barré con escoba y juntá con pala.
Si hay algo pegado, usá un balde, no la manguera.
Tirá lo juntado a la basura, no a la alcantarilla.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],80,0,0,0,'Cada vez: ~80 L de agua',true,'gesto',10,'gratis',false,array[]::text[],'calle',array[]::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/',null,null,array['vereda']::text[],null,true,18),
('agua-no-jugar-con-manguera','daily'::activity_type,'agua','Refrescate sin dejar la manguera abierta','Un rato de manguera abierta son cientos de litros.','En verano dan ganas de jugar con la manguera, pero abierta tira más de 10 litros por minuto. Un balde, una pileta chica o una toalla mojada refrescan igual y el agua alcanza para todos, sobre todo en los días en que la red no da abasto.','Llená un balde o una pileta chica.
Jugá o refrescate con esa agua.
Cuando termines, regá las plantas con lo que quedó.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen']::text[],100,0,0,0,'Cada vez: ~100 L de agua',false,'gesto',5,'gratis',false,array[]::text[],'casa',array['verano']::text[],null,array[]::text[],false,null,null,null,null,null,array['verano','chicos']::text[],null,true,19),
('agua-tapa-pileta','daily'::activity_type,'agua','Tapá la pileta a la noche','Una pileta destapada pierde por evaporación decenas de litros por día.','El sol y el viento evaporan varios milímetros de pileta por día: en una pileta chica son decenas de litros que después se reponen con la manguera. Taparla cuando nadie la usa también la mantiene limpia por más tiempo.','Cuando termines de usarla, cubrila con su lona o una manta térmica.
Sacala recién cuando la vayan a usar.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],30,0,0,0,'Cada vez: ~30 L de agua',false,'gesto',3,'gratis',false,array['pileta']::text[],'casa',array['verano']::text[],null,array[]::text[],false,null,null,null,null,null,array['pileta','verano']::text[],null,true,20),
('agua-ola-de-calor','daily'::activity_type,'agua','En días de calor, dejá para otro día lo que gasta mucha agua','Cuando hace mucho calor, las plantas potabilizadoras trabajan al límite.','En las olas de calor el consumo se dispara y AySA pide priorizar el agua para tomar, cocinar y la higiene. Lavar el auto, baldear o llenar la pileta pueden esperar a un día fresco, y así no le falta presión a nadie.','Si hoy hace mucho calor, no laves el auto ni baldees la vereda.
Si tenés que llenar algo grande, hacelo de noche.
Guardá agua en la heladera para tomar.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],50,0,0,0,'Cada vez: ~50 L de agua',false,'gesto',2,'gratis',false,array[]::text[],'casa',array['verano']::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/',null,null,array['verano','calor']::text[],null,true,21),
('agua-deshumidificador','daily'::activity_type,'agua','Juntá el agua que gotea del aire acondicionado','Un split puede largar varios litros por día de agua limpia que caen al balcón.','El aire acondicionado saca la humedad del ambiente y la tira por la manguera de desagote. Es agua destilada: no sirve para tomar, pero sí para el inodoro, el piso o las plantas.','Poné un balde o un bidón donde gotea el desagote.
Al final del día, usalo para el inodoro, el piso o regar.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],8,0,0,0,'Cada vez: ~8 L de agua',false,'gesto',2,'gratis',false,array['aire']::text[],'casa',array['verano']::text[],null,array[]::text[],false,null,null,null,null,null,array['verano','reuso']::text[],null,true,22),
('agua-guardian-del-dia','daily'::activity_type,'agua','Sé guardián del agua de tu casa por un día','Una misión: que hoy ninguna canilla quede abierta sin que nadie la use.','Hoy sos el guardián del agua. Tu trabajo es revisar canillas, avisar con buena onda cuando alguien deja el agua corriendo y anotar cuántas veces lo salvaste. Al final del día, contale a tu familia cuánta agua cuidaron.','Recorré la casa y fijate que ninguna canilla gotee.
Si ves agua corriendo sin usar, avisá.
A la noche contá cuántas veces cuidaste el agua.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid']::text[],10,0,0,0,'Cada vez: ~10 L de agua',false,'gesto',10,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],true,null,null,null,'guardian-de-casa',2,array['chicos','mision']::text[],null,true,23),
('agua-afeitarse-vaso','daily'::activity_type,'agua','Afeitate con la pileta tapada, no con la canilla abierta','Enjuagar la maquinita en un poco de agua alcanza.','Afeitarse con la canilla abierta tira varios litros cada vez. Con un vaso o la pileta tapada con un poco de agua se enjuaga igual de bien.','Tapá la pileta o llená un vaso.
Enjuagá ahí la maquinita entre pasada y pasada.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['teen','adult']::text[],8,0,0,0,'Cada vez: ~8 L de agua',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['baño']::text[],null,true,24),
('agua-hielo-a-la-planta','daily'::activity_type,'agua','Los hielos que sobran, a una maceta','Se derriten despacio y riegan sin encharcar.','Cuando sobran hielos del vaso o de la cubetera, en vez de tirarlos en la pileta podés ponerlos en una maceta. Se derriten de a poco y la planta toma el agua sin que se escurra.','Juntá los hielos que sobraron.
Ponelos sobre la tierra de una maceta, sin tocar el tallo.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua','semilla',array['kid']::text[],1,0,0,0,'Cada vez: ~1 L de agua',false,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['chicos','plantas']::text[],null,true,25),
('agua-medi-tu-ducha','catalog'::activity_type,'agua','Medí cuánta agua sale de tu ducha','Con un balde y un reloj sabés cuántos litros por minuto te bañan.','Un experimento de 30 segundos: si sabés cuánto larga tu ducha por minuto, sabés cuánto gasta cada baño. La mayoría sale entre 8 y 15 litros por minuto; multiplicado por los minutos de ducha, el número sorprende.','Poné un balde bajo la ducha abierta como siempre durante 30 segundos.
Medí cuántos litros juntaste (un balde común marca las rayitas) y multiplicá por 2.
Multiplicá por los minutos que dura tu ducha: ese es tu gasto.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'one_time'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'aprender',5,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],true,null,null,null,'ducha-y-bano',5,array['ducha','experimento']::text[],null,true,26),
('agua-revisar-el-medidor','catalog'::activity_type,'agua','Buscá pérdidas ocultas con el medidor','Una pérdida dentro de la pared puede correr meses sin que la escuches.','Si tenés medidor de agua, es la forma más fácil de saber si hay una pérdida escondida. Con todo cerrado, el medidor no se tiene que mover. Si se mueve, algo pierde, y conviene buscarlo antes de que aparezca la mancha de humedad.','Cerrá todas las canillas y no uses agua por una hora.
Anotá el número del medidor al empezar y al terminar.
Si cambió, hay una pérdida: revisá inodoros, canillas y el tanque.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'agua','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'tarea',10,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['perdidas']::text[],null,true,27),
('agua-revisar-perdida-inodoro','catalog'::activity_type,'agua','Hacé la prueba del colorante en el inodoro','La pérdida del inodoro es la más común y la que menos se ve.','Una válvula gastada deja correr agua de la mochila al inodoro todo el día, en silencio: pueden ser cientos de litros diarios. La prueba es fácil y la puede hacer cualquiera en casa.','Echá unas gotas de colorante de comida (o un poco de café) en la mochila.
No descargues durante 20 minutos.
Si el agua del inodoro se tiñó, hay pérdida: hay que cambiar la válvula o el flotante.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'agua','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'tarea',25,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],true,null,null,null,'ducha-y-bano',6,array['perdidas','baño','experimento']::text[],null,true,28),
('arregla-una-canilla-o-inodoro-que-pierde','catalog'::activity_type,'agua','Arreglá una canilla que gotea','Una gota por segundo son unos 30 litros por día, todos los días.','Casi siempre es el cuerito o el vástago, que cuestan poco y se cambian con una llave. AySA pide reparar rápido cualquier pérdida: una canilla que gotea tira en un mes lo que una familia toma en meses.','Cerrá la llave de paso de esa canilla o de la casa.
Desarmá la canilla y cambiá el cuerito o el vástago (en la ferretería te dan el mismo).
Si no te animás, pedile a alguien que sepa: el arreglo es corto.','medium'::effort_level,'high'::impact_level,'honor'::verification_type,220,'recurring'::frequency_type,720,'agua','semilla',array['teen','adult']::text[],900,0,0,0,'Cada vez: ~900 L de agua',false,'tarea',30,'bajo',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/',null,null,array['perdidas','arreglo']::text[],null,true,29),
('agua-aireador-canilla','catalog'::activity_type,'agua','Poné aireadores en las canillas','Cuestan poco, se enroscan a mano y bajan el caudal entre 35% y 50%.','El aireador mezcla aire con el agua: el chorro se siente igual pero sale bastante menos. La Guía de Ahorro de Energía de la Ciudad calcula entre un 35% y un 50% menos de consumo en esa canilla.','Fijate si tu canilla tiene rosca en la punta (casi todas tienen).
Comprá un aireador de la medida en la ferretería.
Enroscalo a mano en lugar del que tiene.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'one_time'::frequency_type,0,'agua','semilla',array['teen','adult']::text[],300,0,0,0,'Cada vez: ~300 L de agua',false,'tarea',10,'bajo',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Gobierno de la Ciudad de Buenos Aires','https://static.buenosaires.gob.ar/sites/default/files/2026-04/Gu%C3%ADa%20de%20ahorro%20de%20energ%C3%ADa%20en%20el%20hogar.pdf',null,null,array['arreglo','cocina','baño']::text[],null,true,30),
('agua-botella-en-mochila-inodoro','catalog'::activity_type,'agua','Poné una botella con agua en la mochila del inodoro','Ocupa lugar dentro de la mochila: cada descarga usa un litro menos.','En los inodoros de descarga única, una botella llena dentro de la mochila hace que cada descarga use menos agua sin que se note. Con cinco descargas diarias, son unos 150 litros por mes.','Llená una botella de 1 litro con agua (o con arena para que no flote) y tapala.
Abrí la tapa de la mochila y ponela en un costado, lejos del flotante y la válvula.
Descargá y fijate que todo funcione igual.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'one_time'::frequency_type,0,'agua','semilla',array['teen','adult']::text[],150,0,0,0,'Cada vez: ~150 L de agua',false,'tarea',10,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['baño']::text[],null,true,31),
('agua-revisar-tanque','catalog'::activity_type,'agua','Revisá que el tanque no rebalse','Un flotante trabado puede tirar agua por el rebalse todo el día.','Si tu casa tiene tanque de reserva, el flotante corta el agua cuando se llena. Si se traba, el agua se va por el caño de rebalse sin que nadie lo vea. Conviene mirarlo dos veces por año, y aprovechar para ver si está limpio y tapado.','Subí con cuidado o mirá el caño de rebalse desde abajo.
Si sale agua de forma constante, el flotante no corta: hay que regularlo o cambiarlo.
Fijate que el tanque esté tapado y limpio.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,4320,'agua','semilla',array['adult']::text[],0,0,0,0,null,false,'tarea',15,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['perdidas','tanque']::text[],null,true,32),
('agua-juntar-lluvia','catalog'::activity_type,'agua','Armá un recolector de agua de lluvia','Un tacho bajo la bajada del techo junta cientos de litros en una tormenta.','Un milímetro de lluvia sobre un metro cuadrado de techo es un litro de agua. Un tacho o bidón con tapa bajo la bajada pluvial junta agua de sobra para regar todo el mes. Tapado y vaciado seguido, no cría mosquitos.','Conseguí un tacho o bidón grande con tapa.
Ponelo bajo la bajada del techo o de la canaleta, con una malla arriba para frenar hojas.
Usá esa agua para regar y vaciala dentro de la semana para que no críe mosquitos.','medium'::effort_level,'high'::impact_level,'honor'::verification_type,220,'one_time'::frequency_type,0,'agua','semilla',array['teen','adult']::text[],400,0,0,0,'Cada vez: ~400 L de agua',false,'tarea',45,'gratis',false,array['balcon']::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['lluvia','riego','dengue']::text[],null,true,33),
('agua-balde-de-lluvia','catalog'::activity_type,'agua','Poné un balde a juntar lluvia','La próxima vez que llueva, sacá un balde: esa agua riega sin cloro.','No hace falta un sistema: un balde o una palangana al aire libre durante una lluvia junta varios litros. A las plantas les gusta más que la de la canilla.','Cuando empiece a llover, sacá un balde al patio o al balcón.
Usá esa agua para regar en los días siguientes.
Vaciá lo que quede antes de una semana, para que no críe mosquitos.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,80,'recurring'::frequency_type,72,'agua','semilla',array['kid','teen','adult']::text[],10,0,0,0,'Cada vez: ~10 L de agua',false,'tarea',2,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['lluvia','chicos']::text[],null,true,34),
('reutiliza-aguas-grises-para-el-jardin','catalog'::activity_type,'agua','Regá el jardín con el agua del lavarropas','El agua del último enjuague sale casi limpia y riega de sobra.','El enjuague del lavarropas son decenas de litros que se van por la cloaca. Si usás jabón suave y sin lavandina, esa agua sirve para regar el pasto y los árboles (mejor no la huerta).','Poné la manguera de desagote en un balde o un tacho durante el último enjuague.
Usá esa agua para el pasto o los árboles, no para verduras que se comen crudas.
No lo hagas si lavaste con lavandina.','medium'::effort_level,'medium'::impact_level,'honor'::verification_type,170,'recurring'::frequency_type,168,'agua','semilla',array['teen','adult']::text[],60,0,0,0,'Cada vez: ~60 L de agua',false,'tarea',15,'gratis',false,array['jardin']::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['reuso','lavarropas','riego']::text[],null,true,35),
('agua-pelopincho-reusar','catalog'::activity_type,'agua','Reusá el agua de la pileta inflable','Una pelopincho son cientos de litros: no hace falta tirarlos por la rejilla.','Cuando la vacíes, esa agua todavía sirve: para regar, para limpiar el patio o el auto, para el inodoro. Y si le cambiás menos seguido el agua (con un colador de hojas y tapándola), dura más.','Antes de vaciarla, regá con baldes las plantas y el pasto.
Usá otra parte para limpiar el patio o el auto.
Vaciá el resto en tierra, no en la vereda.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,168,'agua','semilla',array['kid','teen','adult']::text[],300,0,0,0,'Cada vez: ~300 L de agua',false,'tarea',30,'gratis',false,array['pileta']::text[],'casa',array['verano']::text[],null,array[]::text[],true,null,null,null,null,null,array['pileta','verano','reuso']::text[],null,true,36),
('agua-balde-lavar-auto','catalog'::activity_type,'agua','Lavá el auto con balde, no con manguera','Una manguera abierta tira cientos de litros; con dos baldes alcanza.','Lavar el auto con la manguera corriendo puede gastar 300 litros. Con un balde para enjabonar y otro para enjuagar, menos de 30. Y si lo hacés a la sombra, el jabón no se seca y necesitás menos agua.','Llená un balde con agua y detergente y otro con agua limpia.
Lavá por partes con una esponja y enjuagá con un trapo.
Usá la manguera sólo para un enjuague corto final, si hace falta.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,168,'agua','semilla',array['teen','adult']::text[],250,0,0,0,'Cada vez: ~250 L de agua',false,'tarea',30,'gratis',false,array['auto']::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['auto']::text[],null,true,37),
('instala-un-cabezal-de-ducha-de-bajo-caudal','catalog'::activity_type,'agua','Cambiá la flor de la ducha por una de bajo caudal','Se enrosca a mano y baja el consumo de cada ducha sin que se note.','Las flores de ducha eficientes mezclan aire con el agua y bajan el caudal de 12–15 a 7–9 litros por minuto. En una casa de cuatro personas son miles de litros de agua caliente por mes, y gas que no se quema.','Mirá la rosca de tu flor actual (casi todas son estándar).
Comprá una flor de bajo caudal en la ferretería o el corralón.
Desenroscá la vieja, poné cinta de teflón y enroscá la nueva.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'one_time'::frequency_type,0,'agua','semilla',array['adult']::text[],500,4.062,0,22.5,'Cada vez: ~500 L de agua',false,'tarea',15,'bajo',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Gobierno de la Ciudad de Buenos Aires','https://static.buenosaires.gob.ar/sites/default/files/2026-04/Gu%C3%ADa%20de%20ahorro%20de%20energ%C3%ADa%20en%20el%20hogar.pdf',null,null,array['ducha','arreglo']::text[],null,true,38),
('agua-avisar-perdida-calle','catalog'::activity_type,'agua','Reportá una pérdida de agua en la calle','Un caño roto en la vereda tira miles de litros antes de que alguien avise.','Si ves agua limpia saliendo de la vereda, de una tapa o de la calle sin que haya llovido, casi seguro es un caño roto. Las empresas de agua tienen línea y web para reportarlo: un aviso con la dirección exacta acelera el arreglo.','Anotá la dirección exacta (calle, altura y esquina).
Sacá una foto si podés.
Reportalo a la empresa de agua de tu ciudad o al municipio.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,720,'agua','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'social',5,'gratis',false,array[]::text[],'calle',array[]::text[],null,array[]::text[],false,null,'AySA','https://www.aysa.com.ar/',null,null,array['perdidas','barrio']::text[],null,true,39),
('agua-ensenar-a-alguien','catalog'::activity_type,'agua','Enseñale a alguien un truco para ahorrar agua','Lo que contás se multiplica: cada persona que cambia un hábito ahorra todo el año.','Contarle a alguien de tu casa, tu escuela o tu trabajo un truco concreto (el balde en la ducha, la prueba del inodoro, regar temprano) tiene más impacto que hacerlo solo, porque se repite en otra casa.','Elegí un truco que hagas vos.
Contáselo a alguien explicando por qué sirve.
Si lo prueba, contale cuánta agua ahorra.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,336,'agua','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'social',5,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['compartir']::text[],null,true,40),
('agua-calcular-huella','catalog'::activity_type,'agua','Anotá cuánta agua usás en un día','La OMS dice que con 50 litros por persona se cubre lo básico; en Buenos Aires se consumen muchos más.','Contar duchas, descargas, lavados y riegos de un día y multiplicarlos por lo que gasta cada uno da tu número. AySA registra consumos de hasta 250 litros por habitante en verano, cuando la OMS considera que 50 alcanzan para lo básico.','Anotá durante un día cada uso: ducha (10 L/min), inodoro (9 L), lavarropas (50 L), platos, riego.
Sumalos.
Elegí el uso más grande y pensá cómo bajarlo.','medium'::effort_level,'medium'::impact_level,'honor'::verification_type,170,'one_time'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'aprender',15,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],true,null,'Organización Mundial de la Salud','https://www.who.int/news-room/fact-sheets/detail/drinking-water',null,null,array['experimento']::text[],null,true,41),
('agua-acequia-limpia','catalog'::activity_type,'agua','Limpiá la acequia de tu vereda','En Cuyo la acequia riega el árbol de tu vereda: tapada de basura, no llega el agua.','Las acequias son las que mantienen vivo el arbolado de las ciudades de Cuyo. Mantener limpio el tramo frente a tu casa (sin bolsas, hojas acumuladas ni escombros) deja correr el agua hasta los árboles de toda la cuadra.','Sacá bolsas, plásticos y hojas acumuladas del tramo de tu vereda.
No tires restos de poda ni agua con jabón a la acequia.
Tirá lo que juntaste a la basura.','medium'::effort_level,'medium'::impact_level,'honor'::verification_type,170,'recurring'::frequency_type,336,'agua','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'tarea',20,'gratis',false,array[]::text[],'calle',array[]::text[],null,array['cuyo']::text[],false,null,null,null,null,null,array['acequia','arbol','barrio']::text[],null,true,42),
('agua-riego-por-goteo-casero','catalog'::activity_type,'agua','Armá un riego por goteo con una botella','Una botella con agujeritos riega despacio, justo en la raíz, sin que se evapore.','En las zonas secas del país el riego por goteo es la forma más eficiente de regar: el agua va de a poco a la raíz y no se pierde por el costado. Con una botella de plástico se arma en minutos y le das una segunda vida.','Hacé 3 o 4 agujeritos chicos en la tapa de una botella.
Llenala de agua y enterrala boca abajo junto a la planta.
Rellenala cuando se vacíe.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'one_time'::frequency_type,0,'agua','semilla',array['kid','teen','adult']::text[],30,0,0,0,'Cada vez: ~30 L de agua',false,'tarea',15,'gratis',false,array['balcon']::text[],'casa',array[]::text[],null,array[]::text[],true,null,null,null,null,null,array['riego','plantas','reuso']::text[],null,true,43),
('agua-azul-no-tirar-toallitas','daily'::activity_type,'agua_azul','No tires toallitas, hisopos ni pelos al inodoro','Las toallitas no se deshacen: tapan cloacas y llegan a los ríos.','Toallitas húmedas (aunque digan "biodegradables"), hisopos, hilo dental, pelos y algodones no se desintegran en el agua. Tapan las cloacas del barrio y, cuando desbordan, terminan en arroyos y ríos. Van al tacho del baño.','Dejá un tacho con tapa en el baño.
Tirá ahí toallitas, hisopos, algodones y pelos.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0.01,0,'Cada vez: ~10 g de residuos',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['baño','cloacas','chicos']::text[],null,true,44),
('azul-no-tirar-colillas','daily'::activity_type,'agua_azul','No tires colillas al piso ni a la alcantarilla','Una colilla tiene un filtro de plástico y tóxicos que se lavan con la lluvia.','Las colillas son de los residuos que más se encuentran en playas y costas: el filtro es de acetato (un plástico) y está cargado de químicos que se van al agua. Si fumás, apagala y guardala hasta un cesto, o usá un cenicero de bolsillo.','Llevá un cenicero de bolsillo o una latita con tapa.
Apagá la colilla ahí y tirala en un cesto.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua_azul','semilla',array['teen','adult']::text[],0,0,0.001,0,'Cada vez: ~1 g de residuos',true,'gesto',1,'gratis',false,array[]::text[],'calle',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['colillas','calle']::text[],null,true,45),
('azul-alcantarilla-limpia','daily'::activity_type,'agua_azul','Que nada de tu vereda vaya a la alcantarilla','Lo que cae en la boca de tormenta no se trata: va directo al arroyo.','Las bocas de tormenta llevan el agua de lluvia, sin tratar, a arroyos y ríos. Hojas, bolsas, colillas o el agua con detergente de lavar la vereda viajan con ella. Juntá lo que haya en tu cordón antes de que llegue ahí.','Barré tu cordón y juntá lo que haya.
No barras basura ni hojas hacia la boca de tormenta.
No tires agua con detergente o aceite a la calle.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0.05,0,'Cada vez: ~50 g de residuos',false,'gesto',3,'gratis',false,array[]::text[],'calle',array[]::text[],null,array[]::text[],true,null,null,null,null,null,array['alcantarilla','barrio','chicos']::text[],null,true,46),
('disfruta-afuera-sin-generar-residuos','daily'::activity_type,'agua_azul','En la playa, el río o la plaza, volvé con tu basura','Lo que entra a un espacio natural tiene que volver a salir con vos.','En la costa, el río, el camping o la plaza, los cestos se desbordan y el viento se lleva todo al agua. Llevá una bolsa y volvé con tu basura, aunque haya cestos. Si podés, sumá algo que no era tuyo.','Llevá una bolsa para tu basura.
Antes de irte, revisá que no quede nada.
Si ves basura cerca, juntala también.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0.05,0,'Cada vez: ~50 g de residuos',false,'gesto',2,'gratis',false,array[]::text[],'naturaleza',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['playa','rio','naturaleza','chicos']::text[],null,true,47),
('azul-detergente-justo','daily'::activity_type,'agua_azul','Usá la cantidad justa de detergente y jabón','Más espuma no lava más: lo que sobra se va al río.','La mayoría usamos bastante más detergente y jabón de lo necesario. Todo lo que sobra se va por la cloaca, y en muchas ciudades llega a ríos sin tratar del todo. Medir la dosis ahorra plata y química en el agua.','En el lavarropas, usá la medida que dice el envase para tu carga (no más).
Para los platos, unas gotas en la esponja o en un bowl con agua alcanzan.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0.005,0,'Cada vez: ~5 g de residuos',true,'gesto',1,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['detergente','cocina']::text[],null,true,48),
('participa-de-una-limpieza-de-costa-o-rio','catalog'::activity_type,'agua_azul','Sumate a una limpieza de costa, río o arroyo','Lo que se junta en la orilla es lo que no llega al mar.','Organizaciones, clubes de remo, escuelas y municipios hacen limpiezas en costas, ríos y arroyos de todo el país. Además de sacar plástico, muchas registran qué se encontró: esos datos sirven para exigir cambios.','Buscá una limpieza en tu zona o armala con amigos.
Llevá guantes, bolsas y agua.
Separá lo reciclable y anotá qué encontraron más.','medium'::effort_level,'high'::impact_level,'honor'::verification_type,220,'recurring'::frequency_type,720,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,2,0,'Cada bolsa: 2 kg de residuos',false,'social',120,'gratis',false,array[]::text[],'naturaleza',array[]::text[],null,array[]::text[],true,'{"pregunta":"¿Cuántas bolsas juntaste?","unidad":"bolsa","unidades":"bolsas","min":1,"max":6,"def":1,"paso":1,"por":{"waste_kg":2}}'::jsonb,'Programa de las Naciones Unidas para el Medio Ambiente','https://www.unep.org/plastic-pollution',null,null,array['playa','rio','basura','grupo']::text[],null,true,49),
('adopta-una-boca-de-tormenta-y-mantenela-despejad','catalog'::activity_type,'agua_azul','Adoptá la boca de tormenta de tu esquina','Una boca tapada convierte una lluvia normal en una cuadra inundada.','Antes de cada tormenta, sacar hojas, bolsas y botellas de la reja de la boca de tormenta de tu esquina ayuda a que el agua corra y evita que la basura llegue al arroyo. Si está tapada por dentro, reportala al municipio.','Con guantes, sacá hojas y basura de la reja.
Tiralo al cesto (no a la calle).
Si está tapada por dentro, reportala al municipio.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,336,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0.3,0,'Cada vez: ~300 g de residuos',false,'tarea',20,'gratis',false,array[]::text[],'calle',array[]::text[],null,array[]::text[],true,null,null,null,null,null,array['alcantarilla','inundacion','barrio']::text[],null,true,50),
('usa-una-bolsa-para-microfibras-al-lavar','catalog'::activity_type,'agua_azul','Lavá la ropa sintética en una bolsa filtrante','Cada lavado de ropa sintética suelta miles de microfibras de plástico.','Polar, poliéster y ropa deportiva largan microfibras en cada lavado que las plantas de tratamiento no filtran. Lavarlas dentro de una bolsa especial (o una funda de almohada cerrada), en frío y con carga completa, retiene buena parte.','Juntá la ropa sintética (polar, deportiva, poliéster).
Lavala dentro de una bolsa filtrante o una funda cerrada, en frío.
Sacá las fibras que queden en la bolsa y tiralas a la basura, no a la pileta.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'one_time'::frequency_type,0,'agua_azul','semilla',array['teen','adult']::text[],0,0,0.01,0,'Cada vez: ~10 g de residuos',false,'tarea',5,'bajo',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Programa de las Naciones Unidas para el Medio Ambiente','https://www.unep.org/plastic-pollution',null,null,array['microplasticos','ropa','lavarropas']::text[],null,true,51),
('azul-cosmeticos-sin-microplastico','catalog'::activity_type,'agua_azul','Revisá si tus cosméticos tienen microplásticos','Algunas cremas y exfoliantes llevan plástico en polvo que va directo al agua.','En la lista de ingredientes, "polyethylene", "polypropylene" o "nylon" indican microplásticos. Esos productos se enjuagan y terminan en ríos y mares. La próxima vez, elegí alternativas sin ellos.','Leé los ingredientes de exfoliantes, pastas dentales y cremas.
Buscá "polyethylene", "polypropylene" o "nylon".
Cuando se terminen, reemplazalos por opciones sin microplásticos.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'one_time'::frequency_type,0,'agua_azul','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'aprender',10,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['microplasticos','baño']::text[],null,true,52),
('agua-azul-detergente-biodegradable','catalog'::activity_type,'agua_azul','Pasate a un detergente biodegradable','Los fosfatos de algunos detergentes alimentan algas que ahogan arroyos y lagunas.','Lo que baja por la pileta y el lavarropas llega, tarde o temprano, a un río. Los detergentes biodegradables y sin fosfatos se degradan más rápido y no disparan las algas verdes que dejan sin oxígeno al agua.','Cuando se te termine el detergente, buscá uno biodegradable y sin fosfatos.
Si podés, comprálo en recarga.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'agua_azul','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'salida',10,'gratis',false,array[]::text[],'compras',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['detergente','rios','compras']::text[],null,true,53),
('desecha-medicamentos-correctamente','catalog'::activity_type,'agua_azul','Llevá los remedios vencidos a la farmacia','Tirados al inodoro, los remedios llegan al agua: las plantas de tratamiento no los filtran.','Antibióticos, hormonas o analgésicos vencidos no van a la basura común ni al inodoro. Muchas farmacias y municipios tienen contenedores para recibirlos y tratarlos como residuo especial.','Revisá el botiquín y separá lo vencido.
Preguntá en tu farmacia o en el municipio si los reciben.
Llevalos en una bolsa cerrada.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'agua_azul','semilla',array['teen','adult']::text[],0,0,0.1,0,'Cada vez: ~100 g de residuos',false,'salida',15,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['remedios','especiales']::text[],null,true,54),
('agua-azul-juntar-tanza-y-anzuelos','catalog'::activity_type,'agua_azul','Juntá tanza y anzuelos de la orilla','La tanza abandonada enreda aves, tortugas y peces durante años.','En muelles, escolleras y orillas de ríos y lagunas quedan tanzas, anzuelos y plomadas. Son trampas para aves y tortugas. Juntarlos con cuidado (con guantes) y tirarlos cortados en un cesto salva animales.','Con guantes, juntá tanza, anzuelos y plomadas de la orilla.
Cortá la tanza en pedazos chicos antes de tirarla.
Si pescás, llevate siempre lo tuyo.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,336,'agua_azul','semilla',array['teen','adult']::text[],0,0,0.05,0,'Cada vez: ~50 g de residuos',false,'tarea',20,'gratis',false,array['costa']::text[],'naturaleza',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['pesca','rio','aves']::text[],null,true,55),
('azul-pesca-responsable','catalog'::activity_type,'agua_azul','Si pescás, devolvé los chicos y respetá la veda','Un pez chico devuelto hoy es el que se reproduce mañana.','Cada provincia tiene tallas mínimas, cupos y temporadas de veda para proteger la reproducción de especies como el dorado, el surubí o el pejerrey. Conocerlas y respetarlas, y devolver con cuidado lo que no se va a comer, mantiene la pesca para todos.','Averiguá las tallas mínimas y la veda de tu provincia.
Usá anzuelos sin rebaba para devolver mejor.
Devolvé al agua los peces chicos, mojándote las manos antes de tocarlos.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'one_time'::frequency_type,0,'agua_azul','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'aprender',10,'gratis',false,array['costa']::text[],'casa',array[]::text[],null,array[]::text[],false,null,'FAO','https://www.fao.org/publications/home/fao-flagship-publications/the-state-of-world-fisheries-and-aquaculture/es',null,null,array['pesca','rio']::text[],null,true,56),
('elegi-pescado-de-origen-sustentable','catalog'::activity_type,'agua_azul','Elegí pescado de mar argentino y de temporada','El Mar Argentino tiene especies abundantes que casi no se comen acá.','La merluza, la caballa, la anchoíta o el abadejo son del Mar Argentino y muchas veces más baratas que lo importado. Preguntá en la pescadería qué entró fresco y de dónde viene.','En la pescadería, preguntá qué hay fresco y de dónde viene.
Probá especies del Mar Argentino, como la anchoíta o la caballa.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,720,'agua_azul','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'salida',10,'gratis',false,array[]::text[],'compras',array[]::text[],null,array[]::text[],false,null,'INIDEP','https://www.inidep.edu.ar/',null,null,array['pescado','compras','mar']::text[],null,true,57),
('agua-azul-visita-un-humedal','catalog'::activity_type,'agua_azul','Conocé un humedal de tu zona','Los humedales filtran agua, frenan inundaciones y son de lo primero que se rellena.','Lagunas, bañados, esteros, el Delta, la costa del río: los humedales son reservas de agua, refugio de aves y protección contra las inundaciones. Visitar uno (muchas reservas urbanas lo son) es la mejor forma de entender por qué hay que cuidarlos.','Buscá una reserva, laguna o bañado cerca (muchas tienen senderos y son gratuitas).
Andá con binoculares o el celular para fotos.
Volvé con tu basura.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,720,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'salida',120,'gratis',false,array[]::text[],'naturaleza',array[]::text[],null,array[]::text[],false,null,'Ramsar','https://www.ramsar.org/',null,null,array['humedal','reserva','familia']::text[],null,true,58),
('azul-aprender-cuenca','catalog'::activity_type,'agua_azul','Averiguá a qué río va el agua de tu casa','Saber a dónde va tu agua cambia cómo la cuidás.','El agua que usás viene de algún río o acuífero, y la que tirás vuelve a uno. ¿Es el Paraná, el Río de la Plata, el Matanza-Riachuelo, el Salí-Dulce, el Mendoza, un acuífero? Averiguarlo es entender que lo de tu casa y lo del río son lo mismo.','Buscá de dónde toma el agua tu ciudad (la empresa de agua lo informa).
Averiguá a dónde van las cloacas y las lluvias.
Contáselo a tu familia.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'one_time'::frequency_type,0,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'aprender',15,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'ACUMAR','https://www.acumar.gob.ar/',null,null,array['cuenca','rio','chicos']::text[],null,true,59),
('agua-azul-nunca-soltar-globos','catalog'::activity_type,'agua_azul','Festejá sin soltar globos','Cada globo suelto termina en el agua o en el estómago de un animal.','Los globos que se sueltan "al cielo" bajan en algún lado: muchas veces en ríos, costas y el mar, donde tortugas y aves los confunden con comida. Para un festejo, hay mil formas de decorar sin soltar nada.','En los cumpleaños o festejos, no sueltes globos.
Si usás globos de decoración, al final pinchalos y tiralos a la basura.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,720,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0.025,0.01,0,'Cada vez: ~25 g de CO₂',false,'tarea',5,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['globos','fiestas','chicos']::text[],null,true,60),
('azul-humedales-sin-fuego','catalog'::activity_type,'agua_azul','Denunciá quemas en islas, pastizales o humedales','Las quemas en el Delta del Paraná pueden arrasar miles de hectáreas de humedal.','En 2020 los incendios en el Delta del Paraná quemaron cientos de miles de hectáreas. La Ley de Manejo del Fuego prohíbe las quemas sin autorización. Si ves humo o fuego en islas, bañados o pastizales, avisar rápido a la brigada o al 911 hace la diferencia.','Si ves humo o fuego en un humedal o pastizal, anotá la ubicación.
Llamá al 911 o a la brigada de incendios de tu provincia.
No te acerques al fuego.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,720,'agua_azul','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'social',10,'gratis',false,array[]::text[],'casa',array[]::text[],null,array['centro']::text[],false,null,'Boletín Oficial de la República Argentina','https://www.boletinoficial.gob.ar/detalleAviso/primera/239139/20201224',null,null,array['humedal','fuego','participacion']::text[],null,true,61),
('azul-playa-sin-huella','catalog'::activity_type,'agua_azul','En la playa, no dejes nada y no pises los médanos','Los médanos protegen la costa; las colillas y tapitas en la arena terminan en el mar.','En las vacaciones en la costa: los médanos con vegetación frenan la erosión y no se pisan ni se cruzan con vehículos; la basura (sobre todo colillas, tapitas y sorbetes) vuelve con vos; y la fauna, como lobos marinos o aves, se mira de lejos.','Bajá a la playa por los accesos marcados, no por el médano.
Llevá bolsa para tu basura y volvé con ella.
Mirá a la fauna de lejos, sin alimentarla.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,72,'agua_azul','semilla',array['kid','teen','adult']::text[],0,0,0.05,0,'Cada vez: ~50 g de residuos',false,'tarea',5,'gratis',false,array[]::text[],'naturaleza',array['verano']::text[],null,array[]::text[],false,null,null,null,null,null,array['playa','vacaciones','mar']::text[],null,true,62),
('air-ventilar-al-cocinar','daily'::activity_type,'aire_suelo','Ventilá mientras cocinás','El aire de adentro de una casa puede estar más contaminado que el de la calle.','Cocinar a gas, freír o usar el horno libera gases y partículas. La OMS advierte sobre la contaminación del aire dentro de las casas. Abrir una ventana o prender el extractor mientras cocinás, y un rato después, renueva el aire.','Al prender las hornallas, abrí una ventana o prendé el extractor.
Dejalo unos minutos más al terminar.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Organización Mundial de la Salud','https://www.who.int/es/news-room/fact-sheets/detail/household-air-pollution-and-health',null,null,array['aire','cocina','gas']::text[],null,true,63),
('aire-ventilar-corto','daily'::activity_type,'aire_suelo','Ventilá fuerte y corto, no a medias todo el día','Abrir del todo unos minutos renueva el aire sin enfriar ni calentar las paredes.','Una ventana entreabierta todo el día deja escapar la calefacción o el aire acondicionado y casi no renueva. Abrir de par en par 5 a 10 minutos, mejor con ventanas enfrentadas, cambia todo el aire. Si hay mucho tránsito afuera, hacelo fuera de la hora pico.','Abrí ventanas enfrentadas de par en par 5 a 10 minutos.
Cerrá y volvé a la temperatura de siempre.
Si vivís en una avenida, ventilá temprano o tarde, no en hora pico.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,true,'gesto',5,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Gobierno de la Ciudad de Buenos Aires','https://static.buenosaires.gob.ar/sites/default/files/2026-04/Gu%C3%ADa%20de%20ahorro%20de%20energ%C3%ADa%20en%20el%20hogar.pdf',null,null,array['aire']::text[],null,true,64),
('air-limpieza-sin-aerosol','daily'::activity_type,'aire_suelo','Limpiá sin aerosoles','Los aerosoles y desodorantes de ambiente empeoran el aire de tu casa.','Los aerosoles de limpieza y los aromatizantes largan compuestos que quedan flotando en el aire de adentro. Un trapo húmedo, agua con detergente o vinagre limpian casi todo, y para el olor, nada como ventilar.','Para limpiar, usá un trapo húmedo y un producto líquido en vez de aerosol.
Para el olor, ventilá en vez de usar aromatizante.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'aire_suelo','semilla',array['teen','adult']::text[],0,0,0,0,null,true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Organización Mundial de la Salud','https://www.who.int/es/news-room/fact-sheets/detail/household-air-pollution-and-health',null,null,array['aire','limpieza']::text[],null,true,65),
('ene-lena-seca','daily'::activity_type,'aire_suelo','Quemá sólo leña seca y estacionada','La leña húmeda humea más, calienta menos y ensucia el aire del barrio.','En la Patagonia, la montaña y muchas zonas rurales, la leña es la calefacción. La leña verde o mojada gasta su energía en evaporar agua: humea, calienta poco y llena la chimenea de hollín. La seca, guardada bajo techo de un año para el otro, rinde más con menos humo.','Usá leña que suene "hueca" al golpear dos troncos y tenga grietas en las puntas.
Prendé con papel y ramitas secas, no con plástico ni nafta.
Mantené la estufa con buena entrada de aire, sin ahogarla.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0.5,0,0,'Cada vez: ~500 g de CO₂',true,'gesto',2,'gratis',true,array['lena']::text[],'casa',array['otono','invierno']::text[],null,array[]::text[],false,null,'Organización Mundial de la Salud','https://www.who.int/es/news-room/fact-sheets/detail/household-air-pollution-and-health',null,null,array['lena','humo','invierno']::text[],null,true,66),
('aire-asado-sin-plastico','daily'::activity_type,'aire_suelo','Prendé el fuego del asado sin alcohol ni plásticos','Bolsitas, telgopor o alcohol dan humo tóxico y sabor feo.','Para prender el carbón o la leña alcanza con papel de diario, ramitas secas o el clásico "chimenea" de lata. Las bolsas, el telgopor, el alcohol o la nafta largan humo tóxico que respiran todos (y que llega a la carne).','Armá la base con papel de diario y ramitas secas.
Usá una chimenea de lata para prender el carbón.
Nunca uses plásticos, alcohol ni nafta.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'gesto',5,'gratis',false,array['parrilla']::text[],'casa',array[]::text[],'finde',array[]::text[],false,null,null,null,null,null,array['asado','humo']::text[],null,true,67),
('evita-quemar-residuos-al-aire-libre','catalog'::activity_type,'aire_suelo','No quemes la basura: separala y sacala','Quemar basura en el patio libera humo tóxico que respiran tu familia y tus vecinos.','En pueblos y zonas rurales sin recolección es común quemar la basura en el fondo. Plásticos y otros materiales quemados a baja temperatura largan sustancias muy tóxicas. Separar, compostar lo orgánico y llevar lo demás a un punto de recolección cuida el aire y la salud.','Separá lo orgánico para compost y lo reciclable.
Averiguá dónde se recibe la basura en tu localidad (punto de acopio, contenedor, recolección).
No quemes plásticos, gomas ni envases.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,720,'aire_suelo','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'tarea',10,'gratis',false,array['campo']::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Organización Mundial de la Salud','https://www.who.int/es/news-room/fact-sheets/detail/ambient-(outdoor)-air-quality-and-health',null,null,array['campo','humo','basura']::text[],null,true,68),
('air-no-quemar-hojas','catalog'::activity_type,'aire_suelo','Compostá las hojas en vez de quemarlas','El humo de las quemas de hojas es de lo peor para el aire del barrio.','Las hojas del otoño son oro para la tierra: apiladas en un rincón o en la compostera se vuelven mantillo en unos meses. Quemarlas llena el barrio de humo y partículas que afectan sobre todo a chicos y personas con asma.','Juntá las hojas en un rincón del jardín o en bolsas.
Usalas de mantillo sobre los canteros o sumalas al compost.
Nunca las quemes.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,336,'aire_suelo','semilla',array['teen','adult']::text[],0,2.5,5,0,'Cada vez: ~2,5 kg de CO₂',false,'tarea',20,'gratis',false,array['jardin']::text[],'casa',array['otono','invierno']::text[],null,array[]::text[],false,null,'Organización Mundial de la Salud','https://www.who.int/es/news-room/fact-sheets/detail/ambient-(outdoor)-air-quality-and-health',null,null,array['hojas','compost','humo']::text[],null,true,69),
('aire-campo-no-quemar-pastizal','catalog'::activity_type,'aire_suelo','No quemes pastizales ni rastrojos','Una quema "controlada" puede volverse un incendio con un cambio de viento.','La Ley de Manejo del Fuego regula las quemas. Quemar pastizales, banquinas o rastrojos degrada el suelo, mata fauna, llena de humo las rutas y muchas veces se escapa de control. Hay alternativas: pastoreo, corte, incorporación al suelo.','No quemes pastizales, banquinas ni rastrojos.
Consultá con el INTA o la autoridad provincial las alternativas para tu caso.
Si ves una quema que se descontrola, llamá a bomberos o a la brigada.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'one_time'::frequency_type,0,'aire_suelo','semilla',array['adult']::text[],0,0,0,0,null,false,'aprender',10,'gratis',false,array['campo']::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Boletín Oficial de la República Argentina','https://www.boletinoficial.gob.ar/detalleAviso/primera/239139/20201224',null,null,array['campo','fuego','suelo']::text[],null,true,70),
('aire-sierras-sin-fuego','catalog'::activity_type,'aire_suelo','En temporada de incendios, no hagas fuego en las sierras ni el monte','En invierno y primavera, en las sierras, una chispa alcanza para quemar miles de hectáreas.','En Córdoba, San Luis, las sierras del NOA y Cuyo, el fin del invierno es la época de más riesgo: pasto seco, viento y heladas. Si salís a la naturaleza, nada de fuego fuera de los fogones habilitados (mejor ninguno), y las colillas, siempre apagadas y con vos.','Antes de salir, fijate el índice de riesgo de incendio de tu provincia.
No hagas fuego fuera de los fogones habilitados.
Si ves humo, avisá al 911 o a la brigada.','easy'::effort_level,'high'::impact_level,'honor'::verification_type,130,'recurring'::frequency_type,720,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'salida',5,'gratis',false,array[]::text[],'naturaleza',array['invierno','primavera']::text[],null,array['centro','cuyo','noa']::text[],false,null,'Boletín Oficial de la República Argentina','https://www.boletinoficial.gob.ar/detalleAviso/primera/239139/20201224',null,null,array['fuego','sierras','naturaleza']::text[],null,true,71),
('reduci-el-uso-de-lena-o-usa-cocinas-mas-limpias','catalog'::activity_type,'aire_suelo','Guardá la leña bajo techo para que se seque','La leña de este invierno se prepara en verano.','La leña recién cortada tiene mucha agua. Apilada bajo techo, separada del piso y con aire entre los troncos, en unos meses se seca y rinde mucho más, con menos humo. Es el mejor ahorro para quien se calefacciona a leña.','Apilá la leña bajo un techo, sobre palos o pallets, no en el piso.
Dejá aire entre las filas.
Usá primero la que lleva más tiempo guardada.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'aire_suelo','semilla',array['teen','adult']::text[],0,2,0,0,'Cada vez: ~2 kg de CO₂',false,'tarea',30,'gratis',false,array['lena']::text[],'casa',array['verano','otono']::text[],null,array[]::text[],false,null,null,null,null,null,array['lena','invierno']::text[],null,true,72),
('usa-cortadora-manual-o-electrica-en-vez-de-nafta','catalog'::activity_type,'aire_suelo','Cortá el pasto con cortadora eléctrica o manual','Una bordeadora a nafta puede contaminar en una hora tanto como un auto en un viaje largo.','Los motores chicos de dos tiempos (bordeadoras, sopladoras, cortadoras a nafta) son muy contaminantes y ruidosos. Una eléctrica, una manual o simplemente cortar menos seguido y dejar un sector sin cortar cuidan el aire y el oído de la cuadra.','Si tenés que cortar, usá una cortadora eléctrica o manual.
Cortá menos seguido y dejá un sector más alto.
Si es a nafta, mantenela bien regulada.','medium'::effort_level,'medium'::impact_level,'honor'::verification_type,170,'recurring'::frequency_type,168,'aire_suelo','semilla',array['adult']::text[],0,1,0,0,'Cada vez: ~1 kg de CO₂',false,'tarea',45,'gratis',false,array['jardin']::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['jardin','aire','ruido']::text[],null,true,73),
('mejora-la-salud-del-suelo-sin-labranza','catalog'::activity_type,'aire_suelo','No des vuelta la tierra de la huerta','Dar vuelta la tierra rompe la red de hongos y bichitos que la mantiene viva.','La tierra de una huerta es un ecosistema. En lugar de dar vuelta la tierra con la pala, aflojala con una horquilla sin invertirla y sumá compost y mantillo arriba: las lombrices hacen el resto, y retiene más agua.','Aflojá la tierra con una horquilla, sin darla vuelta.
Poné compost por encima.
Cubrí con mantillo.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'aire_suelo','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'tarea',30,'gratis',false,array['huerta']::text[],'casa',array[]::text[],null,array[]::text[],false,null,'FAO','https://www.fao.org/soils-portal/es/',null,null,array['suelo','huerta']::text[],null,true,74),
('aire-cubri-la-tierra-desnuda','catalog'::activity_type,'aire_suelo','No dejes tierra pelada: cubrila','El suelo descubierto se seca, se erosiona y levanta polvo.','La tierra desnuda pierde humedad y vida. Cubrirla con mantillo, plantas rastreras o un abono verde (como avena o vicia en invierno) la protege del sol, la lluvia fuerte y el viento.','Buscá la tierra que quedó pelada en macetas, canteros o el jardín.
Cubrila con hojas secas, pasto cortado o plantas rastreras.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,2160,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'tarea',20,'gratis',false,array['balcon']::text[],'casa',array[]::text[],null,array[]::text[],false,null,'FAO','https://www.fao.org/soils-portal/es/',null,null,array['suelo','chicos']::text[],null,true,75),
('arma-un-cantero-alimentado-con-compost','catalog'::activity_type,'aire_suelo','Armá un cantero con tu compost','Un suelo con compost retiene más agua, más carbono y da más vida.','El compost que hiciste es el mejor punto de partida para un cantero nuevo: mezclado con la tierra, alimenta plantas y bichos del suelo y guarda humedad. Es cerrar el círculo de tus restos de cocina.','Elegí un lugar con sol.
Mezclá una parte de compost cada tres de tierra.
Plantá y cubrí con mantillo.','medium'::effort_level,'medium'::impact_level,'honor'::verification_type,170,'one_time'::frequency_type,0,'aire_suelo','semilla',array['teen','adult']::text[],0,1.5,3,0,'Cada vez: ~1,5 kg de CO₂',false,'tarea',60,'gratis',false,array['compost']::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,'compost-en-casa',5,array['compost','suelo']::text[],null,true,76),
('air-vinagre-y-bicarbonato','catalog'::activity_type,'aire_suelo','Prepará un limpiador casero con vinagre y bicarbonato','Vinagre, bicarbonato y un poco de detergente limpian casi todo.','Para mesadas, vidrios, sarro y grasa liviana, el vinagre blanco y el bicarbonato funcionan muy bien, cuestan poco y no dejan olores químicos en el aire. Guardalos en un rociador reusado y etiquetado.','Mezclá mitad vinagre blanco y mitad agua en un rociador reusado, y etiquetalo.
Para el sarro y la grasa, usá bicarbonato con un poco de agua.
Nunca mezcles vinagre con lavandina.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,80,'recurring'::frequency_type,2160,'aire_suelo','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'tarea',10,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['limpieza','aire']::text[],null,true,77),
('aire-medir-la-calidad-del-aire','catalog'::activity_type,'aire_suelo','Consultá la calidad del aire de tu ciudad','Saber cuándo el aire está peor cambia cuándo salís a correr o ventilás.','Varias ciudades argentinas publican mediciones de calidad del aire, y hay mapas mundiales con estaciones y sensores. Mirarlo te dice qué horas y qué días conviene evitar las avenidas para hacer ejercicio o ventilar.','Buscá si tu ciudad publica la calidad del aire.
Mirá cómo cambia en el día.
Ajustá cuándo ventilás o salís a hacer ejercicio.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,80,'one_time'::frequency_type,0,'aire_suelo','semilla',array['teen','adult']::text[],0,0,0,0,null,false,'aprender',10,'gratis',false,array[]::text[],'celular',array[]::text[],null,array[]::text[],false,null,'Organización Mundial de la Salud','https://www.who.int/es/news-room/fact-sheets/detail/ambient-(outdoor)-air-quality-and-health',null,null,array['aire']::text[],null,true,78),
('aire-analiza-el-suelo-antes-de-plantar','catalog'::activity_type,'aire_suelo','Hacé la prueba del frasco para conocer tu suelo','Un frasco con tierra y agua muestra cuánta arena, limo y arcilla tiene tu suelo.','Poné tierra en un frasco con agua, agitá y dejalo quieto: en un día las capas se separan (arena abajo, limo en el medio, arcilla arriba). Así sabés si tu tierra drena rápido o retiene agua, y qué le conviene.','Llená un tercio de un frasco con tierra y el resto con agua.
Agitá fuerte y dejalo quieto un día.
Mirá el grosor de cada capa y anotalo.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,100,'recurring'::frequency_type,4320,'aire_suelo','semilla',array['kid','teen','adult']::text[],0,0,0,0,null,false,'observar',20,'gratis',false,array['balcon']::text[],'casa',array[]::text[],null,array[]::text[],true,null,'FAO','https://www.fao.org/soils-portal/es/',null,null,array['suelo','experimento','chicos']::text[],null,true,79),
('res-primero-lo-que-vence','daily'::activity_type,'alimentacion','Cociná primero lo que está por vencer','Lo viejo adelante, lo nuevo atrás: así no se pierde nada en el fondo de la heladera.','Buena parte de la comida que se tira en las casas se compró y se olvidó. El PNUMA calcula que los hogares desperdician casi un 60% de toda la comida que se tira en el mundo. Revisar qué está por vencer antes de decidir qué cocinar es la forma más simple de no sumar a esa cuenta.','Abrí la heladera y la alacena antes de decidir qué cocinar.
Elegí lo que vence primero o lo que está más maduro.
Armá la comida alrededor de eso.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],38,0.5,0.2,0,'Cada vez: ~500 g de CO₂',true,'gesto',3,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Programa de las Naciones Unidas para el Medio Ambiente','https://www.unep.org/resources/publication/food-waste-index-report-2024','cocina-sin-desperdicio',1,array['desperdicio','cocina']::text[],null,true,80),
('aprovecha-las-sobras-dia-sin-desperdicio','daily'::activity_type,'alimentacion','Comé las sobras de ayer','Lo que sobró ayer es el almuerzo de hoy: comida ya hecha, sin gastar nada más.','Las sobras que quedan en la heladera son lo primero que se tira. Planear comerlas (tal cual o transformadas en otra cosa) evita tirar comida, y gas, y plata.','Mirá qué quedó de ayer.
Comelo tal cual o transformalo: tarta, revuelto, empanadas, ensalada.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],57,0.75,0.3,0,'Cada vez: ~750 g de CO₂',true,'gesto',2,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['desperdicio','sobras']::text[],null,true,81),
('ali-porcion-justa','daily'::activity_type,'alimentacion','Serví de a poco y repetí si querés','Lo que queda en el plato casi siempre va a la basura; lo que queda en la olla, no.','Servirse de más es la forma más común de tirar comida en la mesa. Si servís de a poco y repetís con hambre, lo que sobra queda en la olla y se guarda.','Serví un poco menos de lo que creés que vas a comer.
Si te quedás con hambre, repetí.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],19,0.25,0.1,0,'Cada vez: ~250 g de CO₂',true,'gesto',1,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,'cocina-sin-desperdicio',2,array['desperdicio','chicos']::text[],null,true,82),
('alim-congela-lo-que-sobro','daily'::activity_type,'alimentacion','Congelá lo que no vas a llegar a comer','El freezer frena el desperdicio: lo que se olvida en la heladera termina en la basura.','Si ves que algo no lo vas a comer a tiempo (sobras, pan, fruta madura, carne que compraste de más), porcionalo y congelalo ese mismo día con la fecha escrita. Así no se pierde y lo tenés listo para un día sin tiempo.','Porcioná lo que sobró en recipientes o bolsas chicas.
Escribí qué es y la fecha.
Congelalo el mismo día.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],57,0.75,0.3,0,'Cada vez: ~750 g de CO₂',true,'gesto',3,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,'cocina-sin-desperdicio',3,array['desperdicio','freezer']::text[],null,true,83),
('ali-pan-duro','daily'::activity_type,'alimentacion','Rescatá el pan duro','Tostadas, budín o pan rallado para las milanesas: nunca es basura.','El pan es de lo que más se tira. El que quedó duro sirve para tostadas, croutons, budín de pan o pan rallado (rallado y guardado en un frasco dura semanas).','Cortalo en rodajas para tostar, o en cubitos para croutons.
Lo que no uses, rallalo y guardalo en un frasco.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],19,0.25,0.1,0,'Cada vez: ~250 g de CO₂',true,'gesto',5,'gratis',false,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['desperdicio','pan']::text[],null,true,84),
('ali-verduras-de-estacion','daily'::activity_type,'alimentacion','Comprá fruta y verdura de estación','Lo de estación está en su mejor momento: más rico, más barato y sin cámaras ni invernaderos.','La fruta y verdura de estación no necesita meses de cámara de frío ni invernaderos calefaccionados. En la verdulería se nota: está más barata y más rica. Preguntá qué entró esta semana.','Preguntá en la verdulería qué está de estación.
Armá la compra de la semana con eso.','easy'::effort_level,'low'::impact_level,'honor'::verification_type,40,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],0,0.2,0,0,'Cada vez: ~200 g de CO₂',false,'gesto',2,'gratis',false,array[]::text[],'compras',array[]::text[],null,array[]::text[],false,null,null,null,null,null,array['estacion','compras','verduleria']::text[],null,true,85),
('ali-legumbres-hoy','daily'::activity_type,'alimentacion','Sumá legumbres a una comida','Lentejas, garbanzos y porotos: proteína barata con una huella mínima.','Las legumbres dan proteína y fibra con muy poca agua, tierra y emisiones, y fijan nitrógeno en el suelo donde crecen. Un guiso de lentejas, garbanzos en la ensalada o porotos en la sopa: hay mil formas.','Elegí una legumbre que tengas o que consigas suelta.
Sumala a una comida: guiso, ensalada, hamburguesas caseras, hummus.','easy'::effort_level,'medium'::impact_level,'honor'::verification_type,50,'daily'::frequency_type,0,'alimentacion','semilla',array['kid','teen','adult']::text[],0,0.3,0,0,'Cada vez: ~300 g de CO₂',true,'gesto',5,'gratis',true,array[]::text[],'casa',array[]::text[],null,array[]::text[],false,null,'Our World in Data','https://ourworldindata.org/food-choice-vs-eating-local',null,null,array['legumbres','cocina']::text[],null,true,86),
('ali-menos-ultraprocesados','daily'::activity_type,'alimentacion','Elegí un producto sin sellos de "exceso en"','Los octógonos negros marcan lo ultraprocesado: menos envase, menos industria, mejor para vos.','Por la ley de etiquetado frontal, los productos con exceso de azúcar, grasas o sodio llevan sellos negros. Elegir hoy una opción sin sellos (fruta, un yogur natural, algo casero) es mejor para la salud y casi siempre viene con menos envoltorio.','En la próxima compra, mirá los sellos negros del frente.
